"""Spoken and measured review, chapter XIII questions 1–7, printed page 310."""
import argparse
import json
from math import cos,pi
from regular_polygon_angles import scene
from regular_polygon_areas import polygon
from regular_polygon_centers import axes
from regular_polygon_definition import rectangle,rhombus,eq_triangle,regular
from triangle_sine_area import area
from vector_scaling import BOOK,ROOT

OUT=ROOT/'geometry-course/textbook/data/regular-polygon-review.json'


def ask(n,title,question,proof,hint,steps,views,checks,refs,caption):
    page=310 if n<=14 else 311
    c=area(n,None,[page],question,proof,hint,steps,views,checks,refs=refs)
    c['id']=f'atanasyan-7-9-selfcheck-chapter-13-{n}-part-1'
    c['title']=f'Вопрос {n}. '+title
    c['source'].update(collection='selfcheck',chapter='XIII',exercise=str(n))
    c['help'][1]['text']=hint;c['answer']={'mode':'manual','prompt':'Сформулируй ответ своими словами. Сопоставь его с доказательством и проверь числовые выводы на рисунках.'}
    c['review']['reviewer']=f'Атанасян и др., Геометрия 7–9, 2023. Исходный вопрос {n} для повторения главы XIII на печатной с. {page}; проверены формулировка, числовые пробы и варианты собственной модели.'
    c['visualization']['model']['description']=c['visualization']['caption']=caption
    return c


def definitions():
    f=ask(1,'Проверь определение','Какие условия нужны, чтобы выпуклый многоугольник был правильным? Дай примеры и объясни, почему одного равенства сторон или углов недостаточно.',
       'У правильного выпуклого многоугольника равны все стороны и все углы. Например, квадрат и равносторонний треугольник правильные. Неквадратный прямоугольник имеет равные углы, но разные стороны; неквадратный ромб имеет равные стороны, но разные углы.',
       'Проверь обе части определения отдельно: обойди стороны, а затем углы.',[
       ('Проверь прямоугольник','У прямоугольника со сторонами 4 и 2 каждый угол прямой. Однако 4 и 2 не равны, так что фигура не удовлетворяет определению.','Равные углы сами по себе не дают правильность.'),
       ('Проверь ромб','У ромба ABCD все стороны по 5, но диагонали различны и один угол острый. Можно сравнить наклон сторон: соседние стороны не перпендикулярны.','Четыре равные стороны не заставляют ромб быть квадратом.'),
       ('Найди правильный пример','У третьей фигуры три стороны по 6 и три угла по 60°. Её периметр 18. Квадрат — ещё один пример с четырьмя равными сторонами и углами по 90°.','Фигура должна быть выпуклой.')],
       [rectangle('Равны углы прямоугольника',4,2),rhombus('Равны стороны ромба'),eq_triangle('Равносторонний треугольник',6)],
       [('Сколько различных длин сторон у первого прямоугольника?','2','Стороны равны попарно: 4 и 2.'),('Каков периметр нового треугольника со стороной 6?','18','Сложи три равные стороны.')],[113],
       'Сравни три фигуры по сторонам и углам. Имена вершин даны в порядке обхода.')
    g=ask(2,'Выведи внутренний угол','Получите величину каждого внутреннего угла правильного n-угольника, объяснив, откуда берётся n−2.',
       'Диагонали из одной вершины выпуклого n-угольника разбивают его на n−2 треугольника. Сумма углов равна (n−2)·180°. Все n углов правильной фигуры равны; каждый равен 180°(n−2)/n.',
       'В числителе сумма углов всех треугольников. Деление на n превращает общую сумму в один угол только для равноугольной фигуры.',[
       ('Разбей пятиугольник','Проведи диагонали из A в несоседние вершины. Получатся три треугольника; у пяти равных углов общая сумма 540°, каждый равен 108°.','Количество диагоналей из A на одно меньше числа полученных треугольников.'),
       ('Запиши общее разбиение','У n вершин n−3 несоседние с A, кроме самой A. Диагонали разбивают фигуру на n−2 треугольника. Для восьмиугольника таких треугольников шесть.','Сумма всех углов 6·180° ещё не является одним углом восьмиугольника.'),
       ('Сверь результат с внешним поворотом','У девятиугольника внешний поворот 360°/9=40°, внутренний угол 140°. То же даёт 180°·7/9.','Внутренний угол и внешний поворот в сумме 180°.')],
       [regular('Разбиение пятиугольника',5),regular('Шесть треугольников восьмиугольника',8),scene('Поворот девятиугольника',9,'exterior')],
       [('Сколько треугольников даёт разбиение восьмиугольника из одной вершины?','6','Вычти 2 из 8.'),('Сколько градусов у внутреннего угла девятиугольника?','140','Вычти 40° из 180°.')],[113],
       'На первых двух рисунках диагонали выходят из A. На последнем отмечен внешний поворот при A.')
    return [f,g]


def circles():
    first=ask(3,'Докажи существование описанной окружности','Сформулируй и докажи теорему об окружности, проходящей через вершины правильного многоугольника. Почему такая окружность ровно одна?',
      'Прими T за точку пересечения внутренних биссектрис при двух соседних вершинах A и B. Углы TAB и TBA — половины равных углов, значит TA=TB. Прилежащие к TB треугольники равны по стороне многоугольника, общей TB и половинам угла при B. Следовательно, TC=TA, и CT делит угол при C пополам. Повторяя рассуждение, получаем равные радиусы до всех вершин. Через три неколлинеарные вершины можно провести только одну окружность.',
      'Не объявляй вершины равноудалёнными заранее. Сначала получи одну пару равных расстояний, затем перенеси её на следующую вершину.',[
      ('Найди первую пару радиусов','В пятиугольнике полууглы при A и B равны. Значит, треугольник TAB равнобедренный и TA=TB.','T строится по биссектрисам равных внутренних углов.'),
      ('Перейди к следующей вершине','Равенство треугольников TAB и TCB даёт TC=TA и половину угла при C. Тот же переход законно повторять до последней вершины.','Для перехода нужны равенство соседних сторон и общая TB.'),
      ('Объясни единственность','Для восьмиугольника равенство всех восьми расстояний даёт существование. Но уже три неколлинеарные вершины определяют единственный центр как пересечение серединных перпендикуляров.','Единственность не требует заново сравнивать восемь окружностей.')],
      [scene('Первые два радиуса к пятиугольнику',5,'sector'),scene('Обход шестиугольника',6,'circle'),scene('Обход восьмиугольника',8,'circle')],
      [('Сколько вершин проверит полный обход шестиугольника?','6','Перенеси равенство на каждую вершину.'),('Сколько неколлинеарных точек уже определяют окружность?','3','Два серединных перпендикуляра к сторонам треугольника пересекаются в единственной точке.')],[114],
      'T — предполагаемый центр, A и B — соседние вершины. Радиусы направлены в вершины.')
    second=ask(4,'Докажи существование вписанной окружности','Почему правильный многоугольник имеет единственную окружность, касающуюся всех его сторон?',
      'Пусть T — центр описанной окружности. Все стороны — равные хорды. Их середины являются основаниями перпендикуляров из T, а расстояния до хорд равны. Поэтому окружность с этим общим радиусом касается каждой стороны в её середине. Центр любой вписанной окружности обязан лежать на внутренних биссектрисах углов, так что он и радиус однозначны.',
      'Сравни перпендикулярные расстояния до прямых сторон. Одного равенства расстояний до вершин для касания недостаточно.',[
      ('Проведи высоты к сторонам','У треугольников TAB с основаниями-сторонами равны два радиуса и основание. Значит, соответствующие высоты TH и TK равны.','В равнобедренном треугольнике высота к основанию попадает в его середину.'),
      ('Проверь, где действительно касание','TH перпендикулярна стороне в H. Окружность радиуса TH касается стороны в H и по той же причине — каждой стороны в её середине.','Линия должна быть перпендикулярна радиусу в точке на самой окружности.'),
      ('Найди обязательный центр','У любого вписанного круга центр равноудалён от сторон каждого угла, значит лежит на его внутренней биссектрисе. Две соседние биссектрисы определяют T. Для нового восьмиугольника точек касания восемь.','Нужны внутренние биссектрисы выпуклой фигуры.')],
      [axes('Две стороны пятиугольника',5,2),axes('Середины сторон шестиугольника',6,2),axes('Новый восьмиугольник',8,2)],
      [('Сколько градусов между TH и стороной в точке касания?','90','Радиус к точке касания перпендикулярен касательной.'),('Сколько разных точек касания у нового восьмиугольника?','8','У каждой стороны по одной середине.')],[114,115],
      'T — центр. H и K — середины двух сторон. Видимая окружность касается сторон изнутри.')
    return [first,second]


def metrics():
    five=ask(5,'Площадь по периметру и апофеме','Выведи площадь правильного многоугольника по его периметру P и радиусу вписанной окружности r.',
       'Разбей многоугольник на треугольники из центра. Высота каждого к своей стороне равна r. Складываем ar/2 по всем сторонам и выносим общий множитель r/2. Сумма оснований равна P, поэтому S=Pr/2.',
       'Высоту опускай к стороне. Радиус до вершины служит боковой стороной центрального треугольника, а не его высотой.',[
       ('Найди общий множитель','В шестиугольнике все центральные треугольники имеют высоту TH. Площадь одного треугольника с основанием a равна ar/2.','При выделении треугольника не теряй делитель два.'),
       ('Сложи основания','Если периметр P, то сумма всех оснований ровно P. При P=24 и r=2√3 площадь 24√3; этот пример соответствует правильному шестиугольнику со стороной 4.','Удваивать периметр не нужно: каждая сторона посчитана однажды.'),
       ('Проверь по квадрату','Для квадрата со стороной 6 вписанный радиус 3 и P=24. Формула даёт 24·3/2=36, что равно 6².','Новая фигура может иметь тот же P при другой апофеме.')],
       [polygon('Центральные треугольники',6,4,'area'),polygon('Основание и высота',6,4,'radii'),polygon('Квадрат со стороной 6',4,3*2**.5,'area')],
       [('Сколько сторон-оснований у шести центральных треугольников?','6','Каждая сторона входит ровно один раз.'),('Чему равна новая площадь квадрата при P=24 и r=3?','36','Вычисли половину произведения 24 и 3.')],[115,116],
       'TA — радиус до вершины, TH — высота к стороне AB. UW имеет длину 1.')
    six=ask(6,'Сторона и апофема через радиус до вершины','Для правильного n-угольника выведи формулы стороны a и вписанного радиуса r через описанный радиус R.',
       'Центральный угол равен 360°/n. Перпендикуляр TH к стороне AB делит её пополам и делит этот угол пополам. В прямоугольном TAH гипотенуза R, угол ATH равен 180°/n. Поэтому AH=R sin(180°/n), TH=R cos(180°/n), a=2R sin(180°/n).',
       'AH — только половина хорды. Синус даёт противолежащий катет, косинус — прилежащую апофему.',[
       ('Раздели центральный угол пополам','При n=6 полный центральный угол 60°, но в TAH угол при T равен 30°. Гипотенуза TA имеет длину R.','Подстановка 60° вместо 30° перепутает полный треугольник с его половиной.'),
       ('Удвой нужный катет','При R=4 у шестиугольника AH=2, следовательно AB=4; TH=2√3. В общем случае сторона — удвоенное произведение R на синус, а апофема не удваивается.','Проверь, что обе формулы называют длину.'),
       ('Измени число сторон','У квадрата угол ATH=45°. При R=4 апофема 2√2, а сторона 4√2. Удвоение R при сохранении n удвоило бы обе длины.','Для другого n сначала пересчитай половинный угол.')],
       [polygon('Половина центрального угла',6,4,'R'),polygon('Апофема и половина хорды',6,4,'radii'),polygon('Квадрат при R=4',4,4,'R')],
       [('Чему равен угол ATH шестиугольника?','30','180° раздели на шесть.'),('Каков коэффициент при √2 в длине стороны квадрата при R=4?','4','Удвой R·sin45°.')],[116],
       'H — середина AB, TH перпендикулярна хорде. TA=R. UW — единичный отрезок.')
    seven=ask(7,'Три стороны в одной окружности','Как выражаются через один и тот же описанный радиус R стороны равностороннего треугольника, квадрата и правильного шестиугольника?',
       'Для n=3,4,6 подставь в a=2R sin(180°/n) углы 60°, 45°, 30° соответственно. Получатся R√3, R√2 и R.',
       'Сравни углы, опирающиеся на соседние вершины. Чем больше равных дуг, тем короче их хорды на том же круге.',[
       ('Восстанови хорду треугольника','При R=2 угол в половине центрального треугольника равен 60°. Сторона равна 2R·√3/2=2√3.','Полная длина хорды вдвое больше противолежащего катета.'),
       ('Проверь квадрат по диагонали','У квадрата диагональ 2R. Сторона равна 2R/√2=R√2. При R=2 её квадрат равен 8.','Диагональ и сторона имеют разные длины.'),
       ('Сверь шестиугольник','Центральный угол 60° превращает треугольник между соседними вершинами в равносторонний. При R=5 сторона 5 и периметр 30.','Равенство стороны и радиуса относится к шестиугольнику.')],
       [polygon('Хорда треугольника при R=2',3,2,'R'),polygon('Хорда квадрата при R=2',4,2,'R'),polygon('Новый шестиугольник при R=5',6,5,'R')],
       [('Чему равен квадрат стороны квадрата при R=2?','8','Возведи 2√2 в квадрат.'),('Каков периметр правильного шестиугольника при R=5?','30','Шесть раз возьми радиус.')],[116],
       'AB — одна из равных хорд, T — центр. Первые две окружности равны; у третьей радиус 5. UW — единица.')
    return [five,six,seven]


def build():return {'bookId':BOOK,'lessons':[*definitions(),*circles(),*metrics()]}


if __name__=='__main__':
    q=argparse.ArgumentParser();q.add_argument('--check',action='store_true')
    s=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if q.parse_args().check:assert OUT.read_text()==s
    else:OUT.write_text(s)
